-- ============================================================
-- นำเข้าคำถามสาขาไฟฟ้า หมวดที่ 11: การประหยัดพลังงานและ Power Factor (Energy Efficiency)
-- ไฟล์นี้รันได้อิสระ ไม่ต้องพึ่งไฟล์อื่น (idempotent)
-- ============================================================

begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'energy_efficiency', 'การประหยัดพลังงานและ Power Factor (Energy Efficiency)', 11
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'energy_efficiency'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การคำนวณขนาดตัวเก็บประจุที่ต้องติดตั้งเพื่อปรับปรุงตัวประกอบกำลัง (Power Factor Correction) จากค่าเดิมไปยังค่าเป้าหมาย ใช้หลักการพื้นฐานอย่างไร', 'คำนวณจากผลต่างของกำลังไฟฟ้ารีแอคทีฟที่ระบบต้องการที่ตัวประกอบกำลังเดิมกับที่ตัวประกอบกำลังเป้าหมาย โดยอาศัยกำลังไฟฟ้าจริง (P) ของระบบซึ่งคงที่ แล้วคำนวณมุมเฟสเดิมและมุมเฟสเป้าหมายจากค่า Power Factor ทั้งสอง เพื่อหาขนาดกำลังไฟฟ้ารีแอคทีฟ (kVAR) ของตัวเก็บประจุที่ต้องติดตั้งเพิ่ม', 'การคำนวณที่แม่นยำช่วยให้เลือกขนาดตัวเก็บประจุที่เหมาะสม ไม่มากเกินไปจนเกิดปัญหา Overcorrection หรือน้อยเกินไปจนไม่บรรลุเป้าหมายที่ต้องการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การคำนวณขนาดตัวเก็บประจุที่ต้องติดตั้งเพื่อปรับปรุงตัวประกอบกำลัง (Power Factor Correction) จากค่าเดิมไปยังค่าเป้าหมาย ใช้หลักการพื้นฐานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การติดตั้งตัวเก็บประจุปรับปรุงตัวประกอบกำลังมากเกินไป (Overcorrection) จนทำให้ Power Factor กลายเป็นแบบ Leading ก่อให้เกิดปัญหาอะไรได้บ้าง', 'อาจทำให้แรงดันไฟฟ้าในระบบสูงขึ้นผิดปกติ โดยเฉพาะในช่วงที่โหลดต่ำ เนื่องจากตัวเก็บประจุยังคงจ่ายกำลังไฟฟ้ารีแอคทีฟเข้าระบบแม้ความต้องการของโหลดลดลง อาจก่อให้เกิดความเสียหายต่ออุปกรณ์ที่ไวต่อแรงดันเกิน และในบางกรณีอาจเพิ่มความเสี่ยงต่อการเกิดเรโซแนนซ์ฮาร์มอนิกในระบบ', 'การออกแบบระบบปรับปรุงตัวประกอบกำลังที่ดีจึงมักใช้ตัวเก็บประจุแบบสวิตช์อัตโนมัติ (Automatic Capacitor Bank) ที่ปรับขนาดการชดเชยตามโหลดจริงแบบไดนามิก แทนที่จะติดตั้งตัวเก็บประจุขนาดคงที่ตลอดเวลา', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การติดตั้งตัวเก็บประจุปรับปรุงตัวประกอบกำลังมากเกินไป (Overcorrection) จนทำให้ Power Factor กลายเป็นแบบ Leading ก่อให้เกิดปัญหาอะไรได้บ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ตัวเก็บประจุปรับปรุงตัวประกอบกำลังแบบขนาดคงที่ (Fixed Capacitor Bank) และแบบสวิตช์อัตโนมัติ (Automatic Capacitor Bank) เหมาะกับลักษณะโหลดที่แตกต่างกันอย่างไร', 'แบบขนาดคงที่เหมาะกับโหลดที่มีลักษณะค่อนข้างสม่ำเสมอตลอดเวลา เช่น มอเตอร์ที่ทำงานต่อเนื่อง เพราะไม่จำเป็นต้องปรับเปลี่ยนขนาดการชดเชยบ่อย ส่วนแบบสวิตช์อัตโนมัติเหมาะกับโหลดที่มีการเปลี่ยนแปลงมากตลอดวัน เพื่อป้องกันปัญหา Overcorrection ในช่วงที่โหลดต่ำ', 'ระบบสวิตช์อัตโนมัติมักใช้ตัวควบคุมที่ตรวจวัด Power Factor แบบเรียลไทม์แล้วสั่งเปิดหรือปิดชุดตัวเก็บประจุแต่ละชุดตามความจำเป็น เพื่อรักษาระดับ Power Factor ให้ใกล้เคียงเป้าหมายตลอดเวลาโดยไม่เกิดการชดเชยมากเกินไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ตัวเก็บประจุปรับปรุงตัวประกอบกำลังแบบขนาดคงที่ (Fixed Capacitor Bank) และแบบสวิตช์อัตโนมัติ (Automatic Capacitor Bank) เหมาะกับลักษณะโหลดที่แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งตัวเก็บประจุปรับปรุงตัวประกอบกำลังในระบบที่มีอุปกรณ์อิเล็กทรอนิกส์กำลังจำนวนมาก จึงต้องพิจารณาความเสี่ยงจากเรโซแนนซ์ฮาร์มอนิก (Harmonic Resonance)', 'เพราะตัวเก็บประจุที่ต่อร่วมกับความเหนี่ยวนำของระบบ (เช่น หม้อแปลง) อาจเกิดความถี่เรโซแนนซ์ขึ้นในระบบ หากความถี่เรโซแนนซ์นี้ตรงหรือใกล้เคียงกับความถี่ฮาร์มอนิกที่เกิดจากอุปกรณ์อิเล็กทรอนิกส์กำลังในระบบ จะทำให้กระแสหรือแรงดันฮาร์มอนิกที่ความถี่นั้นถูกขยายขึ้นอย่างมาก อาจก่อให้เกิดความเสียหายต่อตัวเก็บประจุและอุปกรณ์อื่นในระบบ', 'ในระบบที่มีความเสี่ยงสูง มักแนะนำให้ใช้ตัวเก็บประจุแบบมีชุดกรองฮาร์มอนิก (Detuned Capacitor หรือ Harmonic Filter) แทนตัวเก็บประจุธรรมดา เพื่อเลื่อนความถี่เรโซแนนซ์ของระบบให้ห่างจากความถี่ฮาร์มอนิกหลักที่มีอยู่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งตัวเก็บประจุปรับปรุงตัวประกอบกำลังในระบบที่มีอุปกรณ์อิเล็กทรอนิกส์กำลังจำนวนมาก จึงต้องพิจารณาความเสี่ยงจากเรโซแนนซ์ฮาร์มอนิก (Harmonic Resonance)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การเรียกเก็บค่าปรับ Power Factor จากการไฟฟ้า มีเหตุผลเชิงเศรษฐศาสตร์และวิศวกรรมอย่างไร', 'เมื่อผู้ใช้ไฟฟ้ามี Power Factor ต่ำ ระบบส่งและจำหน่ายไฟฟ้าต้องรองรับกระแสไฟฟ้าปรากฏ (kVA) ที่สูงกว่ากำลังไฟฟ้าจริง (kW) ที่ผู้ใช้ไฟฟ้าใช้งานจริงมาก ทำให้การไฟฟ้าต้องลงทุนโครงสร้างพื้นฐาน เช่น สายไฟและหม้อแปลง ให้มีขนาดใหญ่กว่าที่จำเป็นหากทุกคนมี Power Factor ดี ค่าปรับจึงเป็นกลไกจูงใจให้ผู้ใช้ไฟฟ้าปรับปรุง Power Factor เพื่อลดภาระต่อระบบโดยรวม', 'การลงทุนติดตั้งตัวเก็บประจุปรับปรุง Power Factor มักคุ้มค่าทางเศรษฐศาสตร์ในระยะสั้นถึงปานกลาง เนื่องจากช่วยลดทั้งค่าปรับและอาจช่วยลดการสูญเสียพลังงานในระบบไฟฟ้าภายในโรงงานเองด้วย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การเรียกเก็บค่าปรับ Power Factor จากการไฟฟ้า มีเหตุผลเชิงเศรษฐศาสตร์และวิศวกรรมอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การตรวจสอบพลังงาน (Energy Audit) ในโรงงานอุตสาหกรรมมีขั้นตอนหลักอย่างไร', 'เริ่มจากการรวบรวมข้อมูลการใช้พลังงานในอดีต สำรวจและวัดการใช้พลังงานของอุปกรณ์หลักแต่ละชนิด วิเคราะห์หาจุดที่มีการใช้พลังงานสูงผิดปกติหรือไม่มีประสิทธิภาพ เสนอมาตรการปรับปรุงพร้อมประเมินความคุ้มค่าทางเศรษฐศาสตร์ และติดตามผลหลังดำเนินมาตรการ', 'การตรวจสอบพลังงานที่ดีไม่ได้มุ่งเน้นเพียงการลดค่าไฟฟ้าเท่านั้น แต่ยังพิจารณาผลกระทบต่อกระบวนการผลิตและคุณภาพสินค้าควบคู่กันไป เพื่อให้มาตรการที่เสนอสามารถนำไปปฏิบัติได้จริงโดยไม่กระทบต่อการดำเนินธุรกิจ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การตรวจสอบพลังงาน (Energy Audit) ในโรงงานอุตสาหกรรมมีขั้นตอนหลักอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ค่าความหนาแน่นการใช้พลังงาน (Energy Use Intensity, EUI) คืออะไร และมีประโยชน์อย่างไรในการเปรียบเทียบประสิทธิภาพพลังงาน', 'คือค่าพลังงานที่ใช้ต่อหน่วยพื้นที่หรือหน่วยผลผลิต (เช่น kWh ต่อตารางเมตรต่อปี สำหรับอาคาร) ใช้เป็นดัชนีเปรียบเทียบประสิทธิภาพการใช้พลังงานระหว่างอาคารหรือโรงงานที่มีขนาดแตกต่างกัน โดยไม่ต้องเปรียบเทียบปริมาณการใช้พลังงานรวมโดยตรงซึ่งจะไม่ยุติธรรมหากขนาดต่างกันมาก', 'การใช้ EUI เป็นเกณฑ์เปรียบเทียบ (Benchmarking) ช่วยให้ผู้บริหารอาคารหรือโรงงานทราบว่าประสิทธิภาพการใช้พลังงานของตนอยู่ในระดับใดเมื่อเทียบกับอาคารประเภทเดียวกันในอุตสาหกรรมเดียวกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ค่าความหนาแน่นการใช้พลังงาน (Energy Use Intensity, EUI) คืออะไร และมีประโยชน์อย่างไรในการเปรียบเทียบประสิทธิภาพพลังงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบบริหารจัดการพลังงานอาคาร (Building Energy Management System, BEMS) มีบทบาทอย่างไรในการลดการใช้พลังงานของอาคาร', 'ทำหน้าที่ตรวจติดตามและควบคุมการใช้พลังงานของระบบต่างๆ ในอาคาร เช่น ระบบปรับอากาศ ระบบแสงสว่าง และระบบไฟฟ้าอื่นๆ แบบรวมศูนย์ ช่วยปรับตารางการทำงานให้เหมาะสมกับการใช้งานจริง ตรวจจับความผิดปกติหรือการสูญเปล่าของพลังงาน และให้ข้อมูลสำหรับการวิเคราะห์แนวโน้มการใช้พลังงานในระยะยาว', 'BEMS สมัยใหม่มักเชื่อมโยงกับเซนเซอร์ตรวจจับการใช้งานพื้นที่ สภาพอากาศภายนอก และระบบพยากรณ์โหลด เพื่อปรับการทำงานของระบบต่างๆ ให้เหมาะสมล่วงหน้าแบบอัตโนมัติ ลดการพึ่งพาการปรับตั้งด้วยมนุษย์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบบริหารจัดการพลังงานอาคาร (Building Energy Management System, BEMS) มีบทบาทอย่างไรในการลดการใช้พลังงานของอาคาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มาตรฐานระบบการจัดการพลังงาน ISO 50001 มีแนวคิดหลักอย่างไรในการช่วยองค์กรปรับปรุงประสิทธิภาพพลังงานอย่างต่อเนื่อง', 'อาศัยแนวคิดวงจร Plan-Do-Check-Act (PDCA) คือวางแผนกำหนดเป้าหมายและมาตรการด้านพลังงาน ดำเนินการตามแผน ตรวจสอบผลลัพธ์เทียบกับเป้าหมาย และปรับปรุงแผนงานอย่างต่อเนื่องตามผลที่ได้ เพื่อสร้างระบบการจัดการพลังงานที่ยั่งยืนในระยะยาว ไม่ใช่เพียงโครงการประหยัดพลังงานครั้งเดียว', 'การได้รับการรับรองมาตรฐานนี้ยังช่วยเสริมภาพลักษณ์ด้านความรับผิดชอบต่อสิ่งแวดล้อมขององค์กร และในบางกรณีอาจเป็นเงื่อนไขที่ลูกค้าหรือคู่ค้าต่างประเทศกำหนดไว้สำหรับการทำธุรกิจร่วมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มาตรฐานระบบการจัดการพลังงาน ISO 50001 มีแนวคิดหลักอย่างไรในการช่วยองค์กรปรับปรุงประสิทธิภาพพลังงานอย่างต่อเนื่อง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดหลอดไฟ LED จึงมีประสิทธิภาพการใช้พลังงานสูงกว่าหลอดไส้ (Incandescent) และหลอดฟลูออเรสเซนต์แบบดั้งเดิมอย่างมีนัยสำคัญ', 'หลอดไส้เปลี่ยนพลังงานไฟฟ้าส่วนใหญ่เป็นความร้อนแทนที่จะเป็นแสงสว่าง ทำให้มีประสิทธิภาพต่ำมาก หลอดฟลูออเรสเซนต์มีประสิทธิภาพดีกว่าแต่ยังคงมีการสูญเสียในบัลลาสต์และกระบวนการปล่อยรังสียูวีที่ต้องแปลงเป็นแสงที่มองเห็นได้ผ่านสารเรืองแสง ส่วน LED ใช้หลักการปล่อยแสงจากสารกึ่งตัวนำโดยตรงเมื่อมีกระแสไฟฟ้าไหลผ่าน ซึ่งมีการสูญเสียพลังงานในรูปความร้อนน้อยกว่ามาก', 'นอกจากประสิทธิภาพพลังงานที่สูงกว่าแล้ว หลอด LED ยังมีอายุการใช้งานยาวนานกว่ามาก ลดความถี่ในการเปลี่ยนหลอดและต้นทุนการบำรุงรักษาในระยะยาวได้อย่างมีนัยสำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดหลอดไฟ LED จึงมีประสิทธิภาพการใช้พลังงานสูงกว่าหลอดไส้ (Incandescent) และหลอดฟลูออเรสเซนต์แบบดั้งเดิมอย่างมีนัยสำคัญ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การใช้เซนเซอร์ตรวจจับการเคลื่อนไหว (Occupancy Sensor) ร่วมกับระบบแสงสว่างในอาคาร ช่วยประหยัดพลังงานได้อย่างไร', 'เซนเซอร์จะตรวจจับว่ามีคนอยู่ในพื้นที่นั้นหรือไม่ แล้วสั่งเปิดหรือปิดไฟอัตโนมัติตามการใช้งานจริง แทนที่จะเปิดไฟทิ้งไว้ตลอดเวลาแม้ไม่มีคนใช้งานพื้นที่นั้น ซึ่งช่วยลดการใช้พลังงานที่สูญเปล่าได้อย่างมีนัยสำคัญ โดยเฉพาะในพื้นที่ที่มีการใช้งานไม่สม่ำเสมอ เช่น ห้องน้ำหรือห้องเก็บของ', 'การเลือกความไวและระยะเวลาหน่วงก่อนปิดไฟ (Time Delay) ที่เหมาะสมมีความสำคัญ เพื่อไม่ให้ไฟดับขณะยังมีคนใช้งานอยู่แต่ไม่ได้เคลื่อนไหว เช่น ในห้องประชุมที่คนนั่งนิ่งเป็นเวลานาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การใช้เซนเซอร์ตรวจจับการเคลื่อนไหว (Occupancy Sensor) ร่วมกับระบบแสงสว่างในอาคาร ช่วยประหยัดพลังงานได้อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการควบคุมความสว่างของไฟตามระดับแสงธรรมชาติ (Daylight Harvesting) จึงสามารถช่วยประหยัดพลังงานได้ในพื้นที่ที่มีแสงธรรมชาติเข้าถึง', 'ระบบจะตรวจวัดระดับแสงธรรมชาติที่มีอยู่แล้วปรับลดความสว่างของไฟฟ้าประดิษฐ์ให้พอดีกับความต้องการที่เหลือ แทนที่จะเปิดไฟฟ้าเต็มความสว่างตลอดเวลาโดยไม่คำนึงถึงแสงธรรมชาติที่มีอยู่แล้ว ซึ่งช่วยลดการใช้พลังงานไฟฟ้าสำหรับแสงสว่างได้อย่างมีนัยสำคัญในพื้นที่ที่มีหน้าต่างหรือช่องแสงเพียงพอ', 'ระบบนี้มักทำงานร่วมกับบัลลาสต์หรือไดรเวอร์ไฟที่สามารถหรี่แสงได้ (Dimmable) เพื่อให้ปรับความสว่างได้อย่างต่อเนื่องแทนที่จะเปิดปิดเป็นขั้นบันได', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการควบคุมความสว่างของไฟตามระดับแสงธรรมชาติ (Daylight Harvesting) จึงสามารถช่วยประหยัดพลังงานได้ในพื้นที่ที่มีแสงธรรมชาติเข้าถึง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดการโหลดสูงสุด (Peak Shaving) ด้วยระบบกักเก็บพลังงานแบตเตอรี่มีหลักการทำงานอย่างไร', 'ระบบจะชาร์จพลังงานเก็บไว้ในแบตเตอรี่ในช่วงที่โหลดต่ำ แล้วปล่อยพลังงานออกมาเสริมในช่วงที่โหลดสูงสุด เพื่อลดโหลดสูงสุดที่ต้องดึงจากระบบไฟฟ้าหลัก ซึ่งช่วยลดค่าใช้จ่ายด้านความต้องการพลังไฟฟ้าสูงสุด (Demand Charge) ที่การไฟฟ้าเรียกเก็บตามค่าโหลดสูงสุดในแต่ละเดือน', 'กลยุทธ์นี้มีความคุ้มค่าทางเศรษฐศาสตร์มากขึ้นเมื่อราคาแบตเตอรี่ลดลง และเหมาะสมเป็นพิเศษกับโรงงานหรืออาคารที่มีรูปแบบโหลดสูงสุดในช่วงเวลาสั้นๆ ที่คาดการณ์ได้ชัดเจน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดการโหลดสูงสุด (Peak Shaving) ด้วยระบบกักเก็บพลังงานแบตเตอรี่มีหลักการทำงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวิเคราะห์ค่าไฟฟ้าตามโครงสร้างอัตราตามช่วงเวลา (Time of Use Rate) จึงมีความสำคัญต่อการวางแผนประหยัดพลังงานของโรงงาน', 'เพราะอัตราค่าไฟฟ้าในช่วงเวลาที่มีความต้องการใช้ไฟฟ้าสูงของประเทศ (On-peak) มักสูงกว่าช่วงเวลาที่มีความต้องการต่ำ (Off-peak) มาก การเลื่อนกิจกรรมที่ใช้พลังงานสูงบางส่วนไปทำในช่วง Off-peak แทน สามารถลดค่าไฟฟ้ารวมได้อย่างมีนัยสำคัญ แม้ปริมาณพลังงานที่ใช้รวมทั้งหมดจะเท่าเดิมก็ตาม', 'กระบวนการที่สามารถเลื่อนเวลาได้ง่าย เช่น การชาร์จแบตเตอรี่รถยกไฟฟ้าหรือการเดินเครื่องทำความเย็นสะสม (Thermal Storage) มักเป็นเป้าหมายแรกที่พิจารณาปรับเวลาการทำงานให้สอดคล้องกับโครงสร้างอัตราค่าไฟฟ้า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวิเคราะห์ค่าไฟฟ้าตามโครงสร้างอัตราตามช่วงเวลา (Time of Use Rate) จึงมีความสำคัญต่อการวางแผนประหยัดพลังงานของโรงงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การใช้ระบบทำความเย็นสะสม (Thermal Energy Storage) ในระบบปรับอากาศขนาดใหญ่ มีหลักการประหยัดพลังงานอย่างไร', 'ระบบจะผลิตและเก็บสะสมความเย็น (เช่น ในรูปน้ำแข็งหรือน้ำเย็น) ในช่วงเวลากลางคืนที่ค่าไฟฟ้าถูกกว่าและอากาศเย็นกว่าทำให้เครื่องทำความเย็นทำงานมีประสิทธิภาพสูงกว่า แล้วนำความเย็นที่สะสมไว้มาใช้ในช่วงกลางวันที่มีความต้องการใช้ความเย็นสูงสุด ช่วยลดทั้งค่าไฟฟ้าตามช่วงเวลาและลดขนาดเครื่องทำความเย็นที่ต้องติดตั้งสำหรับรองรับโหลดสูงสุด', 'ระบบนี้เหมาะสมเป็นพิเศษกับอาคารที่มีรูปแบบการใช้ความเย็นเป็นช่วงเวลาชัดเจน เช่น อาคารสำนักงานหรือศูนย์การค้าที่มีโหลดปรับอากาศสูงสุดในช่วงกลางวัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การใช้ระบบทำความเย็นสะสม (Thermal Energy Storage) ในระบบปรับอากาศขนาดใหญ่ มีหลักการประหยัดพลังงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกใช้มอเตอร์ประสิทธิภาพสูง (High Efficiency Motor หรือ Premium Efficiency Motor) จึงคุ้มค่าในระยะยาวแม้จะมีต้นทุนซื้อเริ่มต้นสูงกว่ามอเตอร์ทั่วไป', 'เพราะต้นทุนพลังงานไฟฟ้าตลอดอายุการใช้งานของมอเตอร์ที่ทำงานต่อเนื่องเป็นเวลานาน มักสูงกว่าต้นทุนซื้อเริ่มต้นของมอเตอร์หลายเท่าตัว การเลือกมอเตอร์ประสิทธิภาพสูงแม้จะมีราคาแพงกว่าเล็กน้อย จึงสามารถประหยัดค่าไฟฟ้าสะสมได้มากกว่าส่วนต่างราคาที่จ่ายเพิ่มในช่วงเวลาไม่นาน', 'การวิเคราะห์ความคุ้มค่าทางเศรษฐศาสตร์ของมอเตอร์จึงควรพิจารณาต้นทุนตลอดอายุการใช้งาน (Life Cycle Cost) แทนที่จะพิจารณาเพียงราคาซื้อเริ่มต้น โดยเฉพาะสำหรับมอเตอร์ที่ทำงานเป็นเวลานานในแต่ละวัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกใช้มอเตอร์ประสิทธิภาพสูง (High Efficiency Motor หรือ Premium Efficiency Motor) จึงคุ้มค่าในระยะยาวแม้จะมีต้นทุนซื้อเริ่มต้นสูงกว่ามอเตอร์ทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเดินเครื่องมอเตอร์ที่มีขนาดใหญ่เกินความจำเป็นเทียบกับภาระงานจริง (Oversized Motor) จึงส่งผลเสียต่อประสิทธิภาพการใช้พลังงาน', 'มอเตอร์ที่ทำงานที่ภาระต่ำกว่าพิกัดมากมักมีประสิทธิภาพลดลงจากจุดที่ออกแบบไว้สูงสุด (ซึ่งมักอยู่ที่ภาระประมาณ 75-100% ของพิกัด) เนื่องจากอัตราส่วนของการสูญเสียคงที่ (เช่น Core Loss) ต่อกำลังไฟฟ้าที่ส่งออกจริงมีสัดส่วนสูงขึ้นเมื่อภาระต่ำ', 'การเลือกขนาดมอเตอร์ให้เหมาะสมกับภาระงานจริงจึงเป็นมาตรการประหยัดพลังงานพื้นฐานที่สำคัญ แม้บางครั้งอาจต้องเผื่อขนาดไว้บ้างสำหรับความไม่แน่นอนของภาระในอนาคต แต่ไม่ควรเผื่อมากเกินความจำเป็น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเดินเครื่องมอเตอร์ที่มีขนาดใหญ่เกินความจำเป็นเทียบกับภาระงานจริง (Oversized Motor) จึงส่งผลเสียต่อประสิทธิภาพการใช้พลังงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การใช้ VFD ควบคุมความเร็วรอบมอเตอร์ปั๊มหรือพัดลมแทนการควบคุมด้วยวาล์วหรือแดมเปอร์ ช่วยประหยัดพลังงานได้อย่างมีนัยสำคัญเพราะเหตุใด', 'เพราะกำลังงานที่ปั๊มหรือพัดลมต้องการแปรผันตามกำลังสามของความเร็วรอบโดยประมาณ (ตามกฎ Affinity Laws) การลดความเร็วรอบลงเพียงเล็กน้อยจึงสามารถลดกำลังไฟฟ้าที่ต้องใช้ได้อย่างมาก ต่างจากการควบคุมด้วยวาล์วหรือแดมเปอร์ที่ยังคงให้มอเตอร์ทำงานเต็มความเร็วตลอดเวลา เพียงแต่จำกัดการไหลด้วยความต้านทานเพิ่มเติมซึ่งสูญเสียพลังงานโดยไม่จำเป็น', 'มาตรการนี้เป็นหนึ่งในมาตรการประหยัดพลังงานที่ให้ผลตอบแทนคุ้มค่าที่สุดในหลายกรณี โดยเฉพาะกับระบบที่มีการเปลี่ยนแปลงความต้องการการไหลบ่อยครั้งตลอดวัน เช่น ระบบปรับอากาศหรือระบบสูบน้ำในอาคาร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การใช้ VFD ควบคุมความเร็วรอบมอเตอร์ปั๊มหรือพัดลมแทนการควบคุมด้วยวาล์วหรือแดมเปอร์ ช่วยประหยัดพลังงานได้อย่างมีนัยสำคัญเพราะเหตุใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการบำรุงรักษาระบบไฟฟ้าอย่างสม่ำเสมอ เช่น การขันจุดต่อสายไฟให้แน่น จึงถือเป็นมาตรการประหยัดพลังงานอย่างหนึ่ง', 'จุดต่อที่หลวมมีความต้านทานสูงกว่าปกติ ทำให้เกิดการสูญเสียพลังงานในรูปความร้อนที่จุดนั้น (I²R Loss) มากกว่าที่ควรจะเป็น การบำรุงรักษาให้จุดต่อแน่นสนิทอยู่เสมอช่วยลดการสูญเสียพลังงานที่ไม่จำเป็นนี้ นอกจากจะช่วยประหยัดพลังงานแล้วยังลดความเสี่ยงจากความร้อนสะสมที่อาจนำไปสู่อัคคีภัยด้วย', 'การตรวจสอบด้วยกล้องถ่ายภาพความร้อนเป็นเครื่องมือที่มีประโยชน์มากในการค้นหาจุดต่อที่มีปัญหาเหล่านี้ในระบบไฟฟ้าขนาดใหญ่ที่มีจุดต่อจำนวนมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการบำรุงรักษาระบบไฟฟ้าอย่างสม่ำเสมอ เช่น การขันจุดต่อสายไฟให้แน่น จึงถือเป็นมาตรการประหยัดพลังงานอย่างหนึ่ง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการลดความยาวหรือเพิ่มขนาดหน้าตัดสายไฟฟ้าจึงถือเป็นมาตรการหนึ่งในการประหยัดพลังงาน', 'เพราะการสูญเสียพลังงานในสายไฟฟ้าแปรผันตามกำลังสองของกระแสคูณด้วยความต้านทานของสาย (I²R) การเพิ่มขนาดหน้าตัดสายไฟช่วยลดความต้านทานต่อหน่วยความยาว ในขณะที่การลดความยาวสายช่วยลดความต้านทานรวมโดยตรง ทั้งสองวิธีล้วนช่วยลดการสูญเสียพลังงานในรูปความร้อนตลอดเส้นทางเดินสาย', 'แม้การเพิ่มขนาดสายไฟจะมีต้นทุนเริ่มต้นสูงกว่า แต่ในกรณีที่มีกระแสไหลผ่านสูงและใช้งานต่อเนื่องเป็นเวลานาน การลงทุนเพิ่มขนาดสายอาจคุ้มค่าในระยะยาวจากพลังงานที่ประหยัดได้สะสม ซึ่งเป็นการวิเคราะห์ที่เรียกว่า Economic Cable Sizing', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการลดความยาวหรือเพิ่มขนาดหน้าตัดสายไฟฟ้าจึงถือเป็นมาตรการหนึ่งในการประหยัดพลังงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งระบบตรวจวัดพลังงานย่อย (Sub-metering) ในแต่ละแผนกหรือกระบวนการของโรงงาน จึงช่วยสนับสนุนการประหยัดพลังงานได้', 'การมีข้อมูลการใช้พลังงานแยกตามแผนกหรือกระบวนการ ช่วยให้สามารถระบุจุดที่ใช้พลังงานสูงผิดปกติได้อย่างชัดเจน และสร้างความรับผิดชอบร่วมกันในแต่ละหน่วยงานต่อการใช้พลังงานของตนเอง ต่างจากการมีเพียงมิเตอร์รวมเดียวที่ไม่สามารถแยกแยะได้ว่าส่วนใดใช้พลังงานมากน้อยเพียงใด', 'ข้อมูลจาก Sub-metering ยังเป็นพื้นฐานสำคัญสำหรับการวิเคราะห์แนวโน้มและการตั้งเป้าหมายลดการใช้พลังงานที่เฉพาะเจาะจงในแต่ละส่วนของกระบวนการผลิต ซึ่งมีประสิทธิภาพมากกว่าการตั้งเป้าหมายรวมทั้งโรงงานเพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งระบบตรวจวัดพลังงานย่อย (Sub-metering) ในแต่ละแผนกหรือกระบวนการของโรงงาน จึงช่วยสนับสนุนการประหยัดพลังงานได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการนำความร้อนทิ้ง (Waste Heat Recovery) จากกระบวนการอุตสาหกรรมกลับมาใช้ประโยชน์ จึงถือเป็นมาตรการประหยัดพลังงานที่สำคัญ', 'กระบวนการอุตสาหกรรมหลายประเภทปล่อยความร้อนทิ้งออกสู่สิ่งแวดล้อมโดยไม่ได้ใช้ประโยชน์ เช่น ความร้อนจากไอเสียเครื่องยนต์หรือหม้อไอน้ำ การนำความร้อนเหล่านี้กลับมาใช้ เช่น อุ่นน้ำป้อนหม้อไอน้ำหรือผลิตไฟฟ้าเสริมด้วยระบบ Cogeneration ช่วยเพิ่มประสิทธิภาพการใช้พลังงานโดยรวมของกระบวนการโดยไม่ต้องใช้เชื้อเพลิงเพิ่มเติม', 'การประเมินศักยภาพของความร้อนทิ้งต้องพิจารณาทั้งปริมาณและระดับอุณหภูมิของความร้อนที่มีอยู่ เพื่อเลือกเทคโนโลยีการนำกลับมาใช้ที่เหมาะสม เนื่องจากความร้อนที่อุณหภูมิต่ำมากอาจมีข้อจำกัดในการนำไปใช้ประโยชน์ได้อย่างมีประสิทธิภาพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการนำความร้อนทิ้ง (Waste Heat Recovery) จากกระบวนการอุตสาหกรรมกลับมาใช้ประโยชน์ จึงถือเป็นมาตรการประหยัดพลังงานที่สำคัญ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบผลิตไฟฟ้าและความร้อนร่วม (Combined Heat and Power, CHP หรือ Cogeneration) ให้ประโยชน์ด้านประสิทธิภาพพลังงานอย่างไรเมื่อเทียบกับการผลิตไฟฟ้าและความร้อนแยกกัน', 'ระบบ CHP ใช้ความร้อนที่เหลือจากกระบวนการผลิตไฟฟ้า (ซึ่งปกติจะสูญเสียทิ้งไปในโรงไฟฟ้าทั่วไป) นำมาใช้ประโยชน์เพิ่มเติม เช่น ผลิตไอน้ำสำหรับกระบวนการผลิตหรือทำความร้อน ทำให้ประสิทธิภาพรวมของการใช้เชื้อเพลิงสูงกว่าการผลิตไฟฟ้าและความร้อนแยกจากกันอย่างมีนัยสำคัญ', 'ระบบ CHP เหมาะสมเป็นพิเศษกับโรงงานอุตสาหกรรมที่มีความต้องการทั้งไฟฟ้าและความร้อน (หรือไอน้ำ) พร้อมกันอย่างต่อเนื่อง เช่น โรงงานอาหารหรือโรงงานเคมี ซึ่งสามารถใช้ประโยชน์จากความร้อนเหลือทิ้งได้เต็มที่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบผลิตไฟฟ้าและความร้อนร่วม (Combined Heat and Power, CHP หรือ Cogeneration) ให้ประโยชน์ด้านประสิทธิภาพพลังงานอย่างไรเมื่อเทียบกับการผลิตไฟฟ้าและความร้อนแยกกัน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งฉนวนกันความร้อน (Thermal Insulation) บนท่อไอน้ำหรือถังเก็บของเหลวร้อนในโรงงานอุตสาหกรรม จึงเป็นมาตรการประหยัดพลังงานที่คุ้มค่าและได้รับความนิยม', 'ท่อหรือถังที่ไม่มีฉนวนหรือฉนวนเสื่อมสภาพจะสูญเสียความร้อนออกสู่บรรยากาศตลอดเวลา ทำให้ต้องใช้พลังงานเพิ่มเติมในการรักษาอุณหภูมิของเหลวหรือไอน้ำให้อยู่ในระดับที่ต้องการ การติดตั้งหรือซ่อมแซมฉนวนกันความร้อนช่วยลดการสูญเสียนี้ได้อย่างมีนัยสำคัญ ด้วยต้นทุนการลงทุนที่ไม่สูงมากเมื่อเทียบกับพลังงานที่ประหยัดได้', 'มาตรการนี้มักมีระยะเวลาคืนทุน (Payback Period) สั้น จึงเป็นหนึ่งในมาตรการแรกๆ ที่มักถูกแนะนำในการตรวจสอบพลังงานของโรงงานอุตสาหกรรมที่มีระบบไอน้ำหรือความร้อน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งฉนวนกันความร้อน (Thermal Insulation) บนท่อไอน้ำหรือถังเก็บของเหลวร้อนในโรงงานอุตสาหกรรม จึงเป็นมาตรการประหยัดพลังงานที่คุ้มค่าและได้รับความนิยม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการกำหนดเป้าหมายและตัวชี้วัดประสิทธิภาพพลังงาน (Key Performance Indicator, KPI) ให้ชัดเจน จึงมีความสำคัญต่อความสำเร็จของโครงการประหยัดพลังงาน', 'เพราะการมีเป้าหมายและตัวชี้วัดที่ชัดเจนช่วยให้สามารถติดตามความคืบหน้าได้อย่างเป็นรูปธรรม สร้างแรงจูงใจให้บุคลากรทุกระดับมีส่วนร่วม และช่วยให้ผู้บริหารสามารถประเมินความคุ้มค่าของการลงทุนด้านพลังงานได้อย่างเป็นระบบ แทนที่จะดำเนินมาตรการต่างๆ โดยไม่มีการวัดผลที่ชัดเจน', 'ตัวชี้วัดที่ดีควรปรับตามปัจจัยที่มีผลต่อการใช้พลังงานนอกเหนือการควบคุม เช่น ปริมาณการผลิตหรือสภาพอากาศ เพื่อให้การเปรียบเทียบผลการดำเนินงานในแต่ละช่วงเวลามีความยุติธรรมและสะท้อนประสิทธิภาพที่แท้จริง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการกำหนดเป้าหมายและตัวชี้วัดประสิทธิภาพพลังงาน (Key Performance Indicator, KPI) ให้ชัดเจน จึงมีความสำคัญต่อความสำเร็จของโครงการประหยัดพลังงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการวางแผนโครงการประหยัดพลังงาน จึงควรพิจารณาระยะเวลาคืนทุน (Payback Period) ควบคู่กับผลตอบแทนการลงทุนตลอดอายุโครงการ (Life Cycle Return)', 'ระยะเวลาคืนทุนช่วยให้เห็นภาพความเสี่ยงและสภาพคล่องทางการเงินในระยะสั้น แต่บางมาตรการที่มีระยะเวลาคืนทุนยาวกว่าอาจให้ผลตอบแทนสะสมตลอดอายุการใช้งานสูงกว่ามาตรการที่คืนทุนเร็วแต่ประหยัดพลังงานได้น้อยกว่าในระยะยาว การพิจารณาทั้งสองมุมมองร่วมกันช่วยให้ตัดสินใจลงทุนได้อย่างสมดุลและครบถ้วนมากขึ้น', 'องค์กรที่มีงบประมาณจำกัดมักให้ความสำคัญกับมาตรการที่มีระยะเวลาคืนทุนสั้นก่อน แต่ไม่ควรมองข้ามมาตรการระยะยาวที่อาจให้ผลตอบแทนรวมสูงกว่า โดยเฉพาะหากสามารถจัดหาแหล่งเงินทุนที่เหมาะสมได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการวางแผนโครงการประหยัดพลังงาน จึงควรพิจารณาระยะเวลาคืนทุน (Payback Period) ควบคู่กับผลตอบแทนการลงทุนตลอดอายุโครงการ (Life Cycle Return)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการฝึกอบรมและสร้างความตระหนักด้านการประหยัดพลังงานให้แก่พนักงาน จึงเป็นส่วนสำคัญของโครงการประหยัดพลังงานที่ยั่งยืน แม้จะมีการติดตั้งอุปกรณ์ประหยัดพลังงานครบถ้วนแล้ว', 'เพราะพฤติกรรมการใช้งานของพนักงานมีผลโดยตรงต่อประสิทธิภาพการใช้พลังงานของอุปกรณ์ แม้อุปกรณ์จะมีประสิทธิภาพสูงเพียงใด หากใช้งานอย่างไม่เหมาะสม เช่น เปิดไฟหรือเครื่องปรับอากาศทิ้งไว้โดยไม่จำเป็น ก็ยังคงสูญเสียพลังงานโดยไม่จำเป็นได้เช่นเดิม', 'การสร้างวัฒนธรรมองค์กรที่ตระหนักถึงการประหยัดพลังงานอย่างต่อเนื่อง มักให้ผลลัพธ์ที่ยั่งยืนกว่าการพึ่งพาเทคโนโลยีเพียงอย่างเดียว เนื่องจากพฤติกรรมที่ดีสามารถคงอยู่ได้ตลอดไปโดยไม่ต้องมีการลงทุนเพิ่มเติม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการฝึกอบรมและสร้างความตระหนักด้านการประหยัดพลังงานให้แก่พนักงาน จึงเป็นส่วนสำคัญของโครงการประหยัดพลังงานที่ยั่งยืน แม้จะมีการติดตั้งอุปกรณ์ประหยัดพลังงานครบถ้วนแล้ว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การวิเคราะห์ต้นทุนพลังงานแบบ Marginal Cost of Conservation มีประโยชน์อย่างไรในการจัดลำดับความสำคัญของมาตรการประหยัดพลังงานหลายมาตรการ', 'เป็นการวิเคราะห์ต้นทุนต่อหน่วยพลังงานที่ประหยัดได้ของแต่ละมาตรการ (เช่น บาทต่อ kWh ที่ประหยัดได้) ช่วยให้สามารถเรียงลำดับมาตรการจากที่คุ้มค่าที่สุดไปยังที่คุ้มค่าน้อยที่สุด ทำให้จัดสรรงบประมาณที่มีจำกัดไปยังมาตรการที่ให้ผลตอบแทนสูงสุดก่อน', 'วิธีการนี้มีประโยชน์อย่างมากเมื่อองค์กรมีมาตรการประหยัดพลังงานที่เป็นไปได้หลายสิบหรือหลายร้อยรายการ แต่มีงบประมาณจำกัดที่ไม่สามารถดำเนินการทั้งหมดพร้อมกันได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การวิเคราะห์ต้นทุนพลังงานแบบ Marginal Cost of Conservation มีประโยชน์อย่างไรในการจัดลำดับความสำคัญของมาตรการประหยัดพลังงานหลายมาตรการ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเปรียบเทียบข้อมูลการใช้พลังงานก่อนและหลังดำเนินมาตรการประหยัดพลังงาน (Measurement and Verification, M&V) จึงต้องปรับแก้ด้วยปัจจัยภายนอกที่ไม่ได้ควบคุม เช่น สภาพอากาศหรือปริมาณการผลิต', 'เพราะการใช้พลังงานอาจเปลี่ยนแปลงจากปัจจัยอื่นที่ไม่เกี่ยวข้องกับมาตรการที่ดำเนินการ เช่น ปีที่อากาศร้อนกว่าปกติอาจทำให้ใช้พลังงานปรับอากาศมากขึ้นแม้จะติดตั้งมาตรการประหยัดพลังงานแล้วก็ตาม การปรับแก้ด้วยปัจจัยเหล่านี้ช่วยให้การประเมินผลสะท้อนถึงผลกระทบที่แท้จริงของมาตรการเพียงอย่างเดียว', 'มาตรฐานสากลสำหรับการวัดและพิสูจน์ผลประหยัดพลังงาน เช่น International Performance Measurement and Verification Protocol (IPMVP) ได้กำหนดวิธีการปรับแก้ที่เป็นมาตรฐานเพื่อให้การประเมินผลมีความน่าเชื่อถือและเปรียบเทียบกันได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเปรียบเทียบข้อมูลการใช้พลังงานก่อนและหลังดำเนินมาตรการประหยัดพลังงาน (Measurement and Verification, M&V) จึงต้องปรับแก้ด้วยปัจจัยภายนอกที่ไม่ได้ควบคุม เช่น สภาพอากาศหรือปริมาณการผลิต'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งระบบผลิตไฟฟ้าจากพลังงานแสงอาทิตย์บนหลังคา (Solar Rooftop) จึงถือเป็นมาตรการที่ช่วยทั้งประหยัดพลังงานและลดค่าใช้จ่ายด้านความต้องการพลังไฟฟ้าสูงสุด', 'ระบบ Solar Rooftop ผลิตไฟฟ้าได้มากในช่วงกลางวันซึ่งมักตรงกับช่วงที่อาคารมีความต้องการใช้ไฟฟ้าสูง เช่น จากระบบปรับอากาศ ทำให้สามารถลดปริมาณไฟฟ้าที่ต้องดึงจากระบบไฟฟ้าหลักได้โดยตรงในช่วงเวลานั้น ซึ่งช่วยทั้งลดค่าไฟฟ้าตามหน่วยที่ใช้และอาจช่วยลดค่าความต้องการพลังไฟฟ้าสูงสุดได้ด้วย หากออกแบบขนาดระบบให้เหมาะสมกับรูปแบบโหลด', 'การวิเคราะห์ความคุ้มค่าของระบบ Solar Rooftop ต้องพิจารณารูปแบบการใช้ไฟฟ้าของอาคารนั้นๆ ให้สอดคล้องกับรูปแบบการผลิตไฟฟ้าจากแสงอาทิตย์ เพื่อให้ได้ประโยชน์สูงสุดจากพลังงานที่ผลิตได้โดยตรง แทนที่จะต้องขายไฟฟ้าส่วนเกินคืนเข้าระบบในราคาที่อาจต่ำกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งระบบผลิตไฟฟ้าจากพลังงานแสงอาทิตย์บนหลังคา (Solar Rooftop) จึงถือเป็นมาตรการที่ช่วยทั้งประหยัดพลังงานและลดค่าใช้จ่ายด้านความต้องการพลังไฟฟ้าสูงสุด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบระบบพลังงานทดแทนร่วมกับระบบไฟฟ้าเดิมของอาคาร จึงต้องพิจารณาสมดุลระหว่างการผลิตไฟฟ้าเองกับการใช้ไฟฟ้าจากระบบหลัก (Self-consumption Ratio)', 'เพราะพลังงานที่ผลิตได้จากระบบทดแทน เช่น โซลาร์เซลล์ หากใช้ประโยชน์เองภายในอาคารโดยตรง มักให้มูลค่าทางเศรษฐศาสตร์สูงกว่าการขายไฟฟ้าส่วนเกินกลับเข้าระบบ เนื่องจากราคาขายไฟฟ้าคืนมักต่ำกว่าราคาซื้อไฟฟ้าจากระบบ การออกแบบขนาดระบบให้สอดคล้องกับรูปแบบการใช้ไฟฟ้าจึงช่วยเพิ่มความคุ้มค่าของการลงทุน', 'บางกรณีอาจพิจารณาติดตั้งระบบกักเก็บพลังงานเพิ่มเติมเพื่อเก็บพลังงานส่วนเกินในช่วงกลางวันไว้ใช้ในช่วงเวลาอื่น ซึ่งช่วยเพิ่มสัดส่วนการใช้ไฟฟ้าที่ผลิตเองได้มากขึ้น แต่ต้องพิจารณาต้นทุนของระบบกักเก็บพลังงานประกอบด้วย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบระบบพลังงานทดแทนร่วมกับระบบไฟฟ้าเดิมของอาคาร จึงต้องพิจารณาสมดุลระหว่างการผลิตไฟฟ้าเองกับการใช้ไฟฟ้าจากระบบหลัก (Self-consumption Ratio)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการรักษาคุณภาพไฟฟ้าที่ดี เช่น ลดฮาร์มอนิกและความไม่สมดุล จึงถือเป็นส่วนหนึ่งของการประหยัดพลังงานทางอ้อม', 'เพราะปัญหาคุณภาพไฟฟ้าที่ไม่ดี เช่น ฮาร์มอนิกสูงหรือความไม่สมดุลระหว่างเฟส ทำให้อุปกรณ์ไฟฟ้า เช่น มอเตอร์และหม้อแปลง เกิดความร้อนสูงขึ้นและมีการสูญเสียพลังงานเพิ่มเติมโดยไม่ก่อให้เกิดประโยชน์ในการทำงาน การปรับปรุงคุณภาพไฟฟ้าจึงช่วยลดการสูญเสียพลังงานที่แฝงอยู่เหล่านี้ได้', 'การประหยัดพลังงานทางอ้อมจากการปรับปรุงคุณภาพไฟฟ้ามักไม่ได้รับความสนใจเท่ามาตรการประหยัดพลังงานทางตรง เนื่องจากผลประหยัดที่ได้ไม่ชัดเจนเท่ากับการเปลี่ยนอุปกรณ์ประสิทธิภาพสูงโดยตรง แต่ในระบบที่มีปัญหาคุณภาพไฟฟ้ารุนแรง ผลประหยัดที่ได้อาจมีนัยสำคัญไม่น้อย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการรักษาคุณภาพไฟฟ้าที่ดี เช่น ลดฮาร์มอนิกและความไม่สมดุล จึงถือเป็นส่วนหนึ่งของการประหยัดพลังงานทางอ้อม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรจึงควรมองการประหยัดพลังงานเป็นกระบวนการต่อเนื่อง แทนที่จะเป็นโครงการที่ทำครั้งเดียวแล้วจบ', 'เพราะเทคโนโลยีประหยัดพลังงานมีการพัฒนาอย่างต่อเนื่อง อุปกรณ์เสื่อมสภาพตามเวลาซึ่งอาจส่งผลต่อประสิทธิภาพ รูปแบบการใช้งานของอาคารหรือโรงงานก็เปลี่ยนแปลงไปตามกาลเวลา การติดตามและปรับปรุงอย่างต่อเนื่องจึงช่วยให้องค์กรรักษาและพัฒนาประสิทธิภาพการใช้พลังงานให้ดีขึ้นเรื่อยๆ แทนที่จะปล่อยให้ประสิทธิภาพที่ได้จากมาตรการเดิมค่อยๆ เสื่อมถอยลงตามเวลา', 'แนวคิดนี้สอดคล้องกับหลักการของมาตรฐาน ISO 50001 ที่เน้นการปรับปรุงอย่างต่อเนื่อง (Continuous Improvement) เป็นหัวใจสำคัญของระบบการจัดการพลังงานที่ยั่งยืนในระยะยาว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรจึงควรมองการประหยัดพลังงานเป็นกระบวนการต่อเนื่อง แทนที่จะเป็นโครงการที่ทำครั้งเดียวแล้วจบ'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'energy_efficiency'
group by c.name_th;
